    static let lines: [(id: String, name: String)] = [("solid", "实线"), ("dash", "虚线"), ("dot", "点线"), ("none", "无边框")]

    static func normalize(_ v: String?) -> String {
        var s = v ?? "circle"
        if s == "blob" { s = "pebble" }
        if s == "egg" { s = "hexa" }
        return all.contains { $0.id == s } ? s : "circle"
    }

    private static var cache: [String: [PathOp]] = [:]

    static func ops(_ id: String) -> [PathOp] {
        if let c = cache[id] { return c }
        let o = parse(paths[id] ?? "")
        cache[id] = o
        return o
    }

    enum PathOp { case m(CGPoint), l(CGPoint), c(CGPoint, CGPoint, CGPoint), z }

    /// 只需要支持 M / L / C / Z（绝对坐标）
    static func parse(_ d: String) -> [PathOp] {
        var out: [PathOp] = []
        var nums: [Double] = []
        var cmd: Character = " "
        func flush() {
            switch cmd {
            case "M": var i = 0; while i + 1 < nums.count { out.append(i == 0 ? .m(CGPoint(x: nums[i], y: nums[i+1])) : .l(CGPoint(x: nums[i], y: nums[i+1]))); i += 2 }
            case "L": var i = 0; while i + 1 < nums.count { out.append(.l(CGPoint(x: nums[i], y: nums[i+1]))); i += 2 }
            case "C": var i = 0; while i + 5 < nums.count { out.append(.c(CGPoint(x: nums[i], y: nums[i+1]), CGPoint(x: nums[i+2], y: nums[i+3]), CGPoint(x: nums[i+4], y: nums[i+5]))); i += 6 }
            case "Z", "z": out.append(.z)
            default: break
            }
            nums = []
        }
        var buf = ""
        func endNum() { if !buf.isEmpty, let v = Double(buf) { nums.append(v) }; buf = "" }
        for ch in d {
            if ch.isLetter && ch != "e" {
                endNum(); flush(); cmd = ch
            } else if ch == "-" {
                if !buf.isEmpty && !buf.hasSuffix("e") { endNum() }
                buf.append(ch)
            } else if ch == " " || ch == "," {
                endNum()
            } else {
                if ch == "." && buf.contains(".") { endNum() }
                buf.append(ch)
            }
        }
        endNum(); flush()
        return out
    }
}

/// 网页版的卡片形状（圆形用正圆）
struct CardShape: Shape {
    var id: String

    func path(in r: CGRect) -> Path {
        if id == "circle" { return Path(ellipseIn: r) }
        let sx = r.width / 100, sy = r.height / 100
        func p(_ q: CGPoint) -> CGPoint { CGPoint(x: r.minX + q.x * sx, y: r.minY + q.y * sy) }
        var path = Path()
        for op in CardShapes.ops(id) {
            switch op {
            case .m(let a): path.move(to: p(a))
            case .l(let a): path.addLine(to: p(a))
            case .c(let a, let b, let c): path.addCurve(to: p(c), control1: p(a), control2: p(b))
            case .z: path.closeSubpath()
            }
        }
        return path
    }
}
